def next_smallest_palindrome(n):
    s = str(n)
    length = len(s)

    # Case 1: All 9s
    if s == '9' * length:
        return n + 2

    # Create a candidate by mirroring the left half
    left_half = s[:(length + 1) // 2]

    def make_palindrome(left, length):
        res = left
        if length % 2 == 1:
            res += left[:-1][::-1]
        else:
            res += left[::-1]
        return int(res)

    candidate = make_palindrome(left_half, length)

    if candidate > n:
        return candidate

    # If mirroring didn't work, increment the left half and mirror again
    incremented_left = str(int(left_half) + 1)

    # Handle case where incrementing left half increases digit count (e.g., 99 -> 100)
    if len(incremented_left) > len(left_half):
        # This case is largely covered by the 'all 9s' check, but for safety:
        return make_palindrome('1' + '0' * (len(left_half)), length + 1)

    return make_palindrome(incremented_left, length)
