def search(nums, n):
    low = 0
    high = n - 1

    while low <= high:
        mid = (low + high) // 2

        # Check if mid is the single element
        # Handle boundaries to avoid index out of bounds
        left_val = nums[mid - 1] if mid > 0 else None
        right_val = nums[mid + 1] if mid < n - 1 else None

        if nums[mid] != left_val and nums[mid] != right_val:
            return nums[mid]

        # Determine which side to search
        # In a sorted array where elements appear in pairs, 
        # the first occurrence of a pair is at an even index.
        if mid % 2 == 0:
            if right_val == nums[mid]:
                low = mid + 1
            else:
                high = mid - 1
        else:
            if left_val == nums[mid]:
                low = mid + 1
            else:
                high = mid - 1
    return None
