def get_maxgold(n_matrix, n, m):
    # Create a DP table to store the maximum gold collected at each cell
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Initialize the first column of the DP table
    for i in range(n):
        dp[i][0] = n_matrix[i][0]

    # Fill the DP table column by column
    for j in range(1, m):
        for i in range(n):
            # Possible moves to reach cell (i, j) are from (i-1, j-1), (i, j-1), and (i+1, j-1)
            prev_best = dp[i][j-1]
            if i > 0:
                prev_best = max(prev_best, dp[i-1][j-1])
            if i < n - 1:
                prev_best = max(prev_best, dp[i+1][j-1])

            dp[i][j] = n_matrix[i][j] + prev_best

    # The answer is the maximum value in the last column
    max_gold = 0
    for i in range(n):
        max_gold = max(max_gold, dp[i][m-1])

    return max_gold
