def first_Factorial_Divisible_Number(x):
    if x == 1:
        return 1

    # Prime factorization of x
    temp_x = x
    factors = {}
    d = 2
    while d * d <= temp_x:
        while temp_x % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_x //= d
        d += 1
    if temp_x > 1:
        factors[temp_x] = factors.get(temp_x, 0) + 1

    def get_min_n_for_prime(p, k):
        # Find smallest n such that v_p(n!) >= k
        # Legendre's formula: v_p(n!) = sum(floor(n/p^i))
        low = 1
        high = p * k
        ans = high
        while low <= high:
            mid = (low + high) // 2
            count = 0
            curr = mid
            while curr >= p:
                count += curr // p
                curr //= p
            if count >= k:
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

    max_n = 0
    for p, k in factors.items():
        max_n = max(max_n, get_min_n_for_prime(p, k))

    return max_n
