def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    kx = int(input_data[0])
    ky = int(input_data[1])

    positions = []
    for i in range(2, len(input_data), 2):
        positions.append((int(input_data[i]), int(input_data[i+1])))

    n = len(positions)

    def get_dist(start_x, start_y, end_x, end_y):
        # BFS to find shortest path for knight on 50x50 board
        queue = deque([(start_x, start_y, 0)])
        visited = [[False] * 50 for _ in range(50)]
        visited[start_x][start_y] = True

        moves = [
            (2, 1), (2, -1), (-2, 1), (-2, -1),
            (1, 2), (1, -2), (-1, 2), (-1, -2)
        ]

        while queue:
            cx, cy, d = queue.popleft()
            if cx == end_x and cy == end_y:
                return d

            for dx, dy in moves:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny, d + 1))
        return -1

    # Precompute distance matrix
    # dists[i][j] is distance from pawn i to pawn j
    # dists[n][j] is distance from knight start to pawn j
    dists = [[0] * n for _ in range(n + 1)]
    for i in range(n):
        dists[n][i] = get_dist(kx, ky, positions[i][0], positions[i][1])
        for j in range(n):
            if i != j:
                dists[i][j] = get_dist(positions[i][0], positions[i][1], positions[j][0], positions[j][1])

    memo = {}

    def get_max_moves(mask, last_idx, is_alice):
        state = (mask, last_idx, is_alice)
        if state in memo:
            return memo[state]

        if mask == (1 << n) - 1:
            return 0

        # Current knight position index
        curr_pos_idx = last_idx if last_idx != -1 else n

        if is_alice:
            # Alice wants to maximize total moves
            res = -float('inf')
            for i in range(n):
                if not (mask & (1 << i)):
                    res = max(res, dists[curr_pos_idx][i] + get_max_moves(mask | (1 << i), i, False))
        else:
            # Bob wants to minimize total moves
            res = float('inf')
            for i in range(n):
                if not (mask & (1 << i)):
                    res = min(res, dists[curr_pos_idx][i] + get_max_moves(mask | (1 << i), i, True))

        memo[state] = res
        return res

    print(get_max_moves(0, -1, True))

